data.ecommerce-alerts.yaml:
{
  "apiVersion": 1,
  "groups": [
    {
      "orgId": 1,
      "name": "ecommerce-service",
      "folder": "ecommerce",
      "interval": "1m",
      "rules": [
        {
          "uid": "ecom-a01-error-rate",
          "title": "A1 服务侧错误率 > 5%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "(sum by (service_name) (rate(rpc_server_duration_milliseconds_count{rpc_connect_rpc_error_code=~\"unknown|internal|unavailable|deadline_exceeded|resource_exhausted|data_loss|unimplemented\",service_name!=\"config-service\",service_name!=\"payment-service\"}[5m])) or sum by (service_name) (rate(rpc_server_duration_milliseconds_count{service_name!=\"config-service\",service_name!=\"payment-service\"}[5m])) * 0) / sum by (service_name) (rate(rpc_server_duration_milliseconds_count{service_name!=\"config-service\",service_name!=\"payment-service\"}[5m]))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.05
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "5m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} 服务侧错误率超 5%。去 APM 盘 R3 看错误码分布,明细跳 Jaeger。(payment 已排除:全是 Unimplemented 桩,有真实现后删掉排除)"
          }
        },
        {
          "uid": "ecom-a02-p99",
          "title": "A2 P99 延迟 > 1s",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "histogram_quantile(0.99, sum by (le, service_name) (rate(rpc_server_duration_milliseconds_bucket{service_name!=\"config-service\"}[5m])))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        1000
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "10m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} P99 超 1s(指标单位 ms)。先看 APM R4 runtime 与 R5 DB,再用 trace 下钻。"
          }
        },
        {
          "uid": "ecom-a03-no-traffic",
          "title": "A3 服务无流量(曾有流量)",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "(sum by (service_name) (rate(rpc_server_duration_milliseconds_count{service_name!=\"config-service\"}[1h] offset 1h)) > 0) unless (sum by (service_name) (rate(rpc_server_duration_milliseconds_count{service_name!=\"config-service\"}[10m])) > 0)",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "10m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} 一小时前有流量、现在完全没有。查部署/网关路由/Consul 注册。"
          }
        },
        {
          "uid": "ecom-a04-goroutine-growth",
          "title": "A4 goroutine 持续增长",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "(deriv(go_goroutine_count[30m]) > 0.05) and (go_goroutine_count > 500)",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "30m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} goroutine 数持续上涨(>0.05/s 且已超 500)。泄漏嫌疑,对照最近发版。"
          }
        }
      ]
    },
    {
      "orgId": 1,
      "name": "ecommerce-dependency",
      "folder": "ecommerce",
      "interval": "1m",
      "rules": [
        {
          "uid": "ecom-a05-pool-wait",
          "title": "A5 pgx 空池等待出现",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "sum by (service_name) (rate(pgxpool_empty_acquire_total{service_name!=\"config-service\"}[5m]))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "5m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} 出现连接池空池等待。慢查询占坑或池配小 —— 池耗尽先于数据库挂。"
          }
        },
        {
          "uid": "ecom-a06-db-error-rate",
          "title": "A6 DB 操作错误率 > 1%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "(sum by (service_name) (rate(db_client_operation_errors_total{service_name!=\"config-service\",db_system_name=\"postgresql\"}[5m])) or sum by (service_name) (rate(db_client_operation_duration_seconds_count{service_name!=\"config-service\",db_system_name=\"postgresql\"}[5m])) * 0) / sum by (service_name) (rate(db_client_operation_duration_seconds_count{service_name!=\"config-service\",db_system_name=\"postgresql\"}[5m]))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.01
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "5m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} 的 PG 操作错误率超 1%。查 PG 与到 pg-dev 的网络/TLS。"
          }
        },
        {
          "uid": "ecom-a07-redis-errors",
          "title": "A7 Redis 客户端错误出现",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "sum by (service_name) (rate(redis_client_errors_total{service_name!=\"config-service\"}[5m]))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "5m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "服务 {{ $labels.service_name }} 出现 Redis 客户端错误。查 Dragonfly 连通性;若同时 DB QPS 上涨 = 缓存击穿正在发生。"
          }
        },
        {
          "uid": "ecom-a08-gateway-5xx",
          "title": "A8 网关 5xx 比率 > 1%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "(sum(rate(http_server_request_duration_seconds_count{http_response_status_code=~\"5..\"}[5m])) or sum(rate(http_server_request_duration_seconds_count[5m])) * 0) / sum(rate(http_server_request_duration_seconds_count[5m]))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.01
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "5m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "网关入口 5xx 超 1%(用户已受伤)。APM R1 锁定下游服务;全绿则问题在网关自身。"
          }
        }
      ]
    },
    {
      "orgId": 1,
      "name": "ecommerce-infra",
      "folder": "ecommerce",
      "interval": "1m",
      "rules": [
        {
          "uid": "ecom-a09-node-cpu",
          "title": "A9a 节点 CPU > 85%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "avg by (k8s_node_name) (sum by (k8s_node_name, cpu) (system_cpu_utilization_ratio{state!=\"idle\"}))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.85
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "15m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "节点 {{ $labels.k8s_node_name }} CPU 超 85% 持续 15 分钟。基础设施盘 R2 看趋势,查 top pod。"
          }
        },
        {
          "uid": "ecom-a09b-node-mem",
          "title": "A9b 节点内存 > 90%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "system_memory_utilization_ratio{state=\"used\"}",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.9
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "15m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "节点 {{ $labels.k8s_node_name }} 内存超 90%。集群只有 2 个节点,一台吃紧另一台也接不住,优先看 top pod。"
          }
        },
        {
          "uid": "ecom-a10-disk",
          "title": "A10a 磁盘使用率 > 85%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "system_filesystem_usage_bytes{state=\"used\",type=~\"ext4|xfs\",mountpoint!~\"/var/lib/kubelet/.*\"} / ignoring(state) sum without(state) (system_filesystem_usage_bytes{type=~\"ext4|xfs\",mountpoint!~\"/var/lib/kubelet/.*\"})",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.85
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "30m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "节点 {{ $labels.k8s_node_name }} {{ $labels.mountpoint }} 磁盘超 85%。openebs-lvm 的 PV 全钉在 node1,涨满会带崩 PG/VM/Loki。"
          }
        },
        {
          "uid": "ecom-a10b-inode",
          "title": "A10b inode 使用率 > 80%",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "system_filesystem_inodes_usage{state=\"used\",type=~\"ext4|xfs\",mountpoint!~\"/var/lib/kubelet/.*\"} / ignoring(state) sum without(state) (system_filesystem_inodes_usage{type=~\"ext4|xfs\",mountpoint!~\"/var/lib/kubelet/.*\"})",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0.8
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "30m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "节点 {{ $labels.k8s_node_name }} inode 超 80% —— 磁盘有空间但写不进去的那种满。"
          }
        },
        {
          "uid": "ecom-a11-nodes-reporting",
          "title": "A11 上报节点数 < 2",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "count(count by (k8s_node_name) (system_cpu_utilization_ratio))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "lt",
                      "params": [
                        2
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "10m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "上报主机指标的节点少于 2。collector 掉实例或节点失联 —— 此时其他图的『正常』不可信。"
          }
        },
        {
          "uid": "ecom-a12-otelcol-export-fail",
          "title": "A12 collector 导出失败",
          "condition": "C",
          "data": [
            {
              "refId": "A",
              "relativeTimeRange": {
                "from": 900,
                "to": 0
              },
              "datasourceUid": "P4169E866C3094E38",
              "model": {
                "expr": "(sum(rate(otelcol_exporter_send_failed_metric_points_total[5m])) or vector(0)) + (sum(rate(otelcol_exporter_send_failed_spans_total[5m])) or vector(0)) + (sum(rate(otelcol_exporter_send_failed_log_records_total[5m])) or vector(0))",
                "instant": true,
                "refId": "A"
              }
            },
            {
              "refId": "B",
              "datasourceUid": "__expr__",
              "model": {
                "type": "reduce",
                "expression": "A",
                "reducer": "last",
                "refId": "B"
              }
            },
            {
              "refId": "C",
              "datasourceUid": "__expr__",
              "model": {
                "type": "threshold",
                "expression": "B",
                "refId": "C",
                "conditions": [
                  {
                    "evaluator": {
                      "type": "gt",
                      "params": [
                        0
                      ]
                    }
                  }
                ]
              }
            }
          ],
          "noDataState": "OK",
          "execErrState": "Error",
          "for": "10m",
          "labels": {
